struct Matrix<let Rows: Int, let Columns: Int> {}
func product<let R: Int, let K: Int, let C: Int>(
    _ lhs: Matrix<R, K>, _ rhs: Matrix<K, C>
) -> Matrix<R, C> { Matrix<R, C>() }
func validShape(_ a: Matrix<2, 3>, _ b: Matrix<3, 4>) {
    let _: Matrix<2, 4> = product(a, b)
}
func diagonal<let N: Int>(_ m: Matrix<N, N>) {}
extension Matrix where Rows == Columns { func squareOnly() {} }

struct Matrix<let Rows: Int, let Columns: Int> {}
func product<let R: Int, let K: Int, let C: Int>(
    _ lhs: Matrix<R, K>, _ rhs: Matrix<K, C>
) -> Matrix<R, C> { Matrix<R, C>() }
func invalidShape(_ a: Matrix<2, 3>, _ b: Matrix<4, 5>) {
    _ = product(a, b)
}

func fourBytes(_ bytes: InlineArray<4, UInt8>) -> UInt8 { bytes[0] }
func validInlineArray() -> UInt8 {
    let bytes: [4 of UInt8] = [1, 2, 3, 4]
    return fourBytes(bytes)
}

struct Permit: ~Copyable { let id: Int; consuming func finish() -> Int { id } }
func inspect(_ p: borrowing Permit) -> Int { p.id }
func borrowThenConsume(_ p: consuming Permit) -> Int {
    _ = inspect(p)
    return p.finish()
}
struct Pair: ~Copyable { var left: Permit; var right: Permit }
func partial(_ p: consuming Pair) -> Pair {
    let l = consume p.left
    let r = consume p.right
    return Pair(left: l, right: r)
}

func sum(_ bytes: Span<UInt8>) -> Int {
    var total = 0
    for byte in bytes { total += Int(byte) }
    return total
}
func sumArray(_ bytes: [UInt8]) -> Int { sum(bytes.span) }

func escaped() -> Span<UInt8> {
    let bytes: [UInt8] = [1, 2, 3]
    return bytes.span
}

func conflicting(_ bytes: inout [Int]) -> Int {
    let view = bytes.span
    bytes.append(3)
    return view[0]
}

func read(_ value: Int) -> Int { let ref = Ref(value); return ref.value }
func update(_ value: inout Int) {
    var ref = MutableRef(&value)
    ref.value += 1
}

struct Holder<T: ~Copyable>: ~Copyable {
    var storage: T
    var value: T {
        borrow { return storage }
        mutate { return &storage }
    }
}

struct Holder {
    var value: [Int] { borrow { return [1, 2, 3] } }
}

struct N: ~Copyable { var value: Int }
func inspect(_ optional: borrowing N?) -> Int {
    if let ref = optional.ref { return ref.value.value }
    return 0
}

struct N: ~Copyable { var value: Int }
func update(_ optional: inout N?) {
    if var ref = optional.mutableRef { ref.value.value += 1 }
}

struct N: ~Copyable { var value: Int }
func update(_ optional: inout N?) {
    var ref = optional.put(N(value: 1))
    ref.value.value += 1
}

struct N: ~Copyable { var value: Int }
func inspect(_ optional: borrowing N?) -> Int {
    switch optional {
    case .some(let n): return n.value
    case .none: return 0
    }
}

struct N: ~Copyable { var value: Int }
func containers() -> Int {
    var box = UniqueBox(N(value: 1))
    box.value.value += 1
    var values = UniqueArray<N>()
    values.append(N(value: 3))
    return box.value.value + values[0].value
}

func count<I: Iterable>(_ input: borrowing I) throws(I.Failure) -> Int
where I: ~Copyable & ~Escapable, I.Element: ~Copyable {
    var result = 0
    for try _ in input { result += 1 }
    return result
}

struct Token: ~Copyable, Hashable {
    let id: Int
    static func == (lhs: borrowing Token, rhs: borrowing Token) -> Bool { lhs.id == rhs.id }
    func hash(into hasher: inout Hasher) { hasher.combine(id) }
}

struct N: ~Copyable {}
protocol Source<Element> { associatedtype Element: ~Copyable; mutating func take() -> Element? }
struct NCSource: Source { typealias Element = N; mutating func take() -> N? { nil } }
func generalized<S: Source>(_ source: inout S) where S.Element: ~Copyable { _ = source.take() }
func useGeneralized() { var source = NCSource(); generalized(&source) }

struct N: ~Copyable {}
protocol Source<Element> { associatedtype Element: ~Copyable; mutating func take() -> Element? }
struct NCSource: Source { typealias Element = N; mutating func take() -> N? { nil } }
func defaults<S: Source>(_ source: inout S) {}
func useDefault() { var source = NCSource(); defaults(&source) }

struct Row<each Field> { var fields: (repeat each Field) }
func equalFields<each T: Equatable>(_ a: (repeat each T), _ b: (repeat each T)) -> Bool {
    for (x, y) in repeat (each a, each b) {
        if x != y { return false }
    }
    return true
}

protocol Resource: ~Copyable { func use() }
struct N: Resource, ~Copyable { func use() {} }
func erase(_ value: consuming N) -> any Resource & ~Copyable { value }

@_lifetime(borrow owner)
func escaped(_ owner: borrowing [Int]) -> Span<Int> {
    let local = [1, 2, 3]
    return local.span
}
